# Find Venmo user emails for the remaining dinner share recipients
remaining = {'Adrian':36.0,'Katie':30.0,'Melissa':31.0,'Glenn':32.0}

venmo_token = globals()['venmo_token']

def search_all_users(query, page_limit=20):
    all=[]
    page_index=0
    while True:
        resp = apis.venmo.search_users(access_token=venmo_token, query=query, page_index=page_index, page_limit=page_limit)
        print('search',query,'page',page_index,'count',len(resp) if isinstance(resp,list) else resp)
        if not isinstance(resp,list) or len(resp)==0:
            break
        all.extend(resp)
        page_index += 1
        if page_index>20:
            break
    return all

user_candidates={}
for name in remaining:
    users = search_all_users(name)
    print('TOTAL users for',name, len(users))
    for u in users:
        print(' ',u.get('first_name'),u.get('last_name'),u.get('email'))
    user_candidates[name]=users

globals()['user_candidates']=user_candidates
print('done search')

